-- Mensaje 122 · El examen 7.3: el argumento del hueco depende del caso (Cerebro 4.3).
UPDATE public.nodes SET practice_script = $g${"notes": "v2.0.0 EXAMEN de desarrollo de cuenta (CAMPO, Emilio). Sin ayudas. El Actor da su pedido pase lo que pase: la falla invisible es el criterio central. Se puede terminar con el pedido en la mano y reprobar. v2.0.4 (mensaje 122, 2-nov-2026): el argumento del hueco depende del caso; la consolidacion no es universal (Cerebro 4.3).", "scope": {"skills_in_focus": ["discovery.lee_el_lugar", "discovery.hueco", "presentation.consolidacion_proveedor", "closing.cerrar_incremento", "consolidation.rehash"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 18, "max_duration_seconds": 360, "min_turns_before_evaluation": 5}, "phases": {"i_do": {"briefing": "El examen del cliente que ya te compra. Todo junto: mapear, encontrar el hueco, presentarlo sin atacar a nadie, cerrar el incremento y salir sin volver a vender.\n\nEl cliente te va a dar su pedido y quedarse contento hagas lo que hagas. Nadie te va a avisar si lo hiciste mal.", "first_message": "Buenas don [nombre]! Ya lo veo con trabajo desde temprano. Como le fue con la quincena pasada?"}, "you_do": {"prompt": "REGLA NUMERO CERO: eres un cliente CONTENTO y sin ningun problema. Si te preguntan si algo anda mal, contestas con sinceridad que no. NUNCA inventes dolores ni quejas.\n\nEres el dueno de un negocio que le compra a este vendedor desde hace anos. Buena relacion, lo recibes con gusto. Adopta el tipo de negocio y las familias de producto del contexto de la empresa.\n\nEN TU PRIMER O SEGUNDO TURNO le das tu pedido de siempre sin que te lo pida, con cantidades.\n\nTU CATALOGO, fijo toda la sesion: 1 o 2 familias se las compras a ESTE vendedor. Otras 2 se las compras a OTRO proveedor desde hace anos y estas conforme. Y hay 1 que tus clientes te piden y tu no manejas, asi que los mandas a otro lado.\n\nCOMO REACCIONAS:\n1) SI SOLO LEVANTA EL PEDIDO y se despide: le agradeces, quedas contento y la visita termina bien. NO le insinuas que hay mas.\n2) SI TE PREGUNTA POR TU CATALOGO o por lo que te piden y no tienes: se lo cuentas con naturalidad.\n3) SI ATACA A TU OTRO PROVEEDOR: defiendes tu decision y te cierras.\n4) SI TE DA UNA RAZON QUE CORRESPONDE A TU CASO —para la familia que hoy le compras a otro, tener menos proveedores; para la que no manejas, que ya te visita, que se vende junto con lo que ya le compras, o una condicion concreta—: te interesa de verdad y preguntas mas. Si para la familia que no manejas te dice que asi tendras menos proveedores, no te convence: no te reduce nada.\n5) SI TE PIDE QUE PRUEBES algo: te da desconfianza y te echas para atras.\n6) SI TE DA CONVICCION CON RAZON sin garantizar: te da confianza y avanzas.\n7) SI CIERRA PREGUNTANDO si quieres: dices que lo piensas. SI ASUME Y TE DA ALTERNATIVA: contestas y queda cerrado.\n8) SI DESPUES DE CERRAR VUELVE A VENDER: te entra la duda de si hiciste bien.\n\nTU PEDIDO BASE NUNCA SE CANCELA.\n\nResponde en 1 o 2 frases, natural.", "objective": "El vendedor ejecuta la visita completa a un cliente recurrente: abre sin volverla tramite, mapea el catalogo y descubre al menos un hueco real, lo presenta con consolidacion sin atacar al proveedor actual, cierra el incremento asumiendo, y se despide sin volver a vender. El scope se cubre cuando el incremento queda confirmado."}, "closing": {"message": "Hasta aqui el examen. Ese cliente te habria dado su pedido y se habria quedado contento aunque no hicieras nada mas. Vamos al desglose y vemos que tanto creciste la cuenta.", "message_incomplete": "Hasta aqui el examen. Vamos al desglose."}}, "version": "2.0.4", "i_do_type": "demo", "failure_criteria": [{"id": "solo_levanta_pedido", "regla_id": "develop.visita_tramite", "severity": "critical", "description": "Sale unicamente con el pedido de siempre, sin explorar nada. La visita parece exitosa y no lo fue: la cuenta no crecio.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "ataca_al_proveedor", "regla_id": "present.ataca_proveedor", "severity": "critical", "description": "Critica o minimiza al proveedor actual del cliente."}, {"id": "hueco_inventado", "regla_id": "discovery.hueco_inventado", "severity": "critical", "description": "Afirma que al cliente le falta algo o que lo necesita sin ninguna base, o contradice lo que el cliente dijo. Preguntar, apoyarse en negocios como el suyo o decir lo que ve no es inventar."}, {"id": "garantiza", "regla_id": "present.garantiza", "severity": "critical", "description": "Garantiza que el producto se vendera o que no fallara.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "pregunta_si_quiere", "regla_id": "close.mal_cierre", "severity": "major", "description": "Pide la decision con una pregunta que se contesta con un no o un dejeme pensarlo: de interes (le interesa?), de opinion (que le parece?) o de si o no sobre la compra (se lo mando?, le aparto 10 cajas?). Todas son igual de graves.", "severity_override": {"razon": "incidental: error de otro paso", "default": "critical"}}, {"id": "vuelve_a_vender", "regla_id": "consolidation.sigue_vendiendo", "severity": "major", "description": "Despues del si sigue justificando la compra.", "severity_override": {"razon": "incidental: error de otro paso", "default": "critical"}}, {"id": "pide_que_pruebe", "regla_id": "present.pide_que_pruebe", "severity": "minor", "description": "Le pide al cliente que pruebe, pasandole el riesgo a el.", "severity_override": {"razon": "incidental: error de otro paso", "default": "major"}}], "success_criteria": [{"id": "discovery.lee_el_lugar", "weight": 0.2, "regla_id": "discovery.lee_el_lugar", "description": "Mapea el catalogo del cliente mas alla de lo que ya le vende: que otras familias maneja y de quien las trae."}, {"id": "discovery.hueco", "weight": 0.25, "regla_id": "discovery.hueco", "description": "Descubre al menos un hueco concreto: una familia con nombre que el cliente compra en otro lado o que le piden y no maneja. Salir solo con el pedido de siempre no cumple."}, {"id": "presentation.consolidacion_proveedor", "weight": 0.2, "regla_id": "present.argumento_del_hueco", "description": "Presenta el hueco con un argumento que corresponde a SU caso: que gana el con que tu se lo surtas. Consolidacion solo si de verdad le reduce proveedores (la familia se la compra hoy a otro); si es una familia que no maneja, la razon es conveniencia (ya lo visitas), complementariedad o una condicion concreta. Sin atacar al proveedor actual, con conviccion respaldada por una razon, sin garantizar y sin pedir que pruebe."}, {"id": "closing.cerrar_incremento", "weight": 0.2, "regla_id": "close.cierra_solo_incremento", "description": "Cierra el incremento asumiendo, con alternativa, sin reabrir el pedido base y sin preguntar si lo quiere."}, {"id": "consolidation.rehash", "weight": 0.15, "regla_id": "consolidation.rehash", "description": "Despues del si, cierra la visita sin volver a vender y deja puesta la siguiente visita (o un referido amarrado a algo que el cliente dijo)."}]}$g$::jsonb WHERE id = '7.3' AND practice_script->>'version' = '2.0.3';
DO $chk$ BEGIN
  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '7.3') IS DISTINCT FROM '14819af949b7763d00ba92713f7af540' THEN RAISE EXCEPTION 'el guion del 7.3 no quedó'; END IF;
END $chk$;
